searchBook.requestInfo:
@js:

let url = config.host.replace("bookshelf.", "so.") + "/ajax/real/search_result"
let hp = {
    "q": params.keyWord,
    "noTab": "0",
    "tabId": "360",
    "sogou_huichuan_hippy": "1",
    "jump_from": "1_01_22_01",
}
return {
    "url": url,
    "httpParams": hp,
    "httpHeaders": config.httpHeaders,
    //"forbidCookie": true,
    "cacheTime": 0,
}

