chapterContent.requestInfo:
@js:

let url = `${config.host.replace("bookshelf.", "novel.")}/be-api/content/ads-read`
let match = params.queryInfo.url.match(/(.*?)_(.*)/)

let hp = {
	"Scene": "chapter",
	"ContentAnchorBatch": [{
		"BookID": match[1],
		"ChapterSeqNo": [match[2]]
	}]
}

let hh = {
    "Host": "novel.html5.qq.com",
    "Q-GUID": "fixture-guid",
    "Content-Type": "application/json",
    "user-agent": "Mozilla/5.0 (Linux; U; Android 13; zh-cn; V2183A Build/TP1A.220624.014) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/89.0.4389.72 MQQBrowser/13.4 Mobile Safari/537.36 COVC/046223"
}

return {
    "url": url,
    "POST": true,
    "httpParams": hp,
    "httpHeaders": hh,
    "cacheTime": 0
}
